/* C API of the Rust port of `position.c`, generated by rust-anything. */
#ifndef POSITION_RS_H
#define POSITION_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

int anchor_x(int x, int old_width, int was_right, int origin, int width, int cell, int right);
int snap_axis(int value, int origin, int cell);
int drag_axis(int value, int origin, int width, int margin, int item);

/* The same functions under `rust_anything_` names, for shadow runs. */
int rust_anything_anchor_x(int x, int old_width, int was_right, int origin, int width, int cell, int right);
int rust_anything_snap_axis(int value, int origin, int cell);
int rust_anything_drag_axis(int value, int origin, int width, int margin, int item);

#endif /* POSITION_RS_H */
